fn algo(id: &str, extra: Value) -> Value {
    let mut im = serde_json::json!({ "id": id, "tech": "typescript", "role": "algorithm", "name": id, "composes": [], "code": "//" });
    if let Value::Object(o) = extra {
        for (k, v) in o {
            im[k] = v;
        }
    }
    im
}

